  more: [{ serial: 'S96', after: 0, alt: 'The red ball rolling down the yard' }, { serial: 'S1364', after: 2, alt: 'Mia and Sam each pointing at a different ball' }, { serial: 'S1365', after: 4, alt: 'Mia hugging the red ball to her chest' }],
