  more: [{ serial: 'S108', after: 0, alt: 'Rain on a window, the girl waiting inside' }, { serial: 'S1415', after: 2, alt: 'A rainbow arching over the fence' }, { serial: 'S1417', after: 5, alt: 'The whole rainbow with every color in a row' }],
